-- Moat's databases on SQLite, first migration (DT-03, DT-13). Generated by `prisma migrate diff`,
-- then the CHECK constraints and triggers were written by hand (CLAUDE.md, Database): Prisma does
-- not model them. A table redefinition in a later migration must copy them. JSON fields are
-- compared with `IS` (NULL-safe): a missing field must fail the CHECK, not pass it as NULL.

-- CreateTable
CREATE TABLE "history_entry" (
    "seq" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT CHECK ("seq" >= 1),
    "at" TEXT NOT NULL CHECK ("at" GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9].[0-9][0-9][0-9]Z'),
    "kind" TEXT NOT NULL CHECK ("kind" IN ('history_started', 'bundle_signed', 'secret_sealed', 'deploy', 'config_edited', 'database_pushed', 'database_pulled')),
    "details" TEXT NOT NULL CHECK (json_valid("details") AND json_type("details") IS 'object' AND length("details") <= 4096),
    "prev_hash" TEXT NOT NULL CHECK (length("prev_hash") = 64 AND "prev_hash" NOT GLOB '*[^0-9a-f]*'),
    "hash" TEXT NOT NULL CHECK (length("hash") = 64 AND "hash" NOT GLOB '*[^0-9a-f]*')
);

-- CreateTable
CREATE TABLE "sync_project" (
    "key" TEXT NOT NULL PRIMARY KEY CHECK (length("key") BETWEEN 1 AND 63 AND substr("key", 1, 1) BETWEEN 'a' AND 'z' AND "key" NOT GLOB '*[^a-z0-9-]*'),
    "config_text" TEXT NOT NULL CHECK (length(CAST("config_text" AS BLOB)) <= 262144),
    "config_hash" TEXT NOT NULL CHECK (length("config_hash") = 64 AND "config_hash" NOT GLOB '*[^0-9a-f]*'),
    "revision" INTEGER NOT NULL CHECK ("revision" >= 1),
    "updated_at" TEXT NOT NULL CHECK ("updated_at" GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9].[0-9][0-9][0-9]Z')
);

-- CreateTable
CREATE TABLE "sync_gate" (
    "project" TEXT NOT NULL,
    "name" TEXT NOT NULL CHECK (length("name") BETWEEN 1 AND 63 AND substr("name", 1, 1) BETWEEN 'a' AND 'z' AND "name" NOT GLOB '*[^a-z0-9-]*'),
    "text" TEXT NOT NULL CHECK (json_valid("text") AND json_extract("text", '$.moat') IS 'gate' AND json_type("text", '$.gateId') IS 'text' AND json_type("text", '$.boxKey') IS 'text' AND length("text") <= 4096),

    PRIMARY KEY ("project", "name"),
    CONSTRAINT "sync_gate_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project" ("key") ON DELETE CASCADE ON UPDATE CASCADE
);

-- CreateTable
-- Ciphertext only (SEC-31): the text must be a sealed secret of this version, nothing else.
CREATE TABLE "sync_secret" (
    "project" TEXT NOT NULL,
    "gate" TEXT NOT NULL CHECK (length("gate") BETWEEN 1 AND 63 AND substr("gate", 1, 1) BETWEEN 'a' AND 'z' AND "gate" NOT GLOB '*[^a-z0-9-]*'),
    "name" TEXT NOT NULL CHECK (length("name") BETWEEN 1 AND 63 AND substr("name", 1, 1) BETWEEN 'a' AND 'z' AND "name" NOT GLOB '*[^a-z0-9-]*'),
    "secret_version" INTEGER NOT NULL CHECK ("secret_version" >= 1),
    "text" TEXT NOT NULL CHECK (json_valid("text") AND json_extract("text", '$.alg') IS 'x25519-blake2b-xchacha20poly1305' AND json_extract("text", '$.secretVersion') IS "secret_version" AND json_type("text", '$.epk') IS 'text' AND json_type("text", '$.nonce') IS 'text' AND json_type("text", '$.ct') IS 'text' AND length("text") <= 65536),

    PRIMARY KEY ("project", "gate", "name"),
    CONSTRAINT "sync_secret_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project" ("key") ON DELETE CASCADE ON UPDATE CASCADE
);

-- CreateTable
CREATE TABLE "sync_bundle" (
    "project" TEXT NOT NULL,
    "gate" TEXT NOT NULL CHECK (length("gate") BETWEEN 1 AND 63 AND substr("gate", 1, 1) BETWEEN 'a' AND 'z' AND "gate" NOT GLOB '*[^a-z0-9-]*'),
    "version" INTEGER NOT NULL CHECK ("version" BETWEEN 1 AND 999999999),
    "digest" TEXT NOT NULL CHECK (length("digest") = 64 AND "digest" NOT GLOB '*[^0-9a-f]*'),
    "text" TEXT NOT NULL CHECK (json_valid("text") AND json_extract("text", '$.moat') IS 'bundle' AND json_type("text", '$.payload') IS 'text' AND length(CAST("text" AS BLOB)) <= 1048576),

    PRIMARY KEY ("project", "gate", "version"),
    CONSTRAINT "sync_bundle_project_fkey" FOREIGN KEY ("project") REFERENCES "sync_project" ("key") ON DELETE CASCADE ON UPDATE CASCADE
);

-- CreateIndex
CREATE UNIQUE INDEX "history_entry_hash_key" ON "history_entry"("hash");

-- The history is append-only: a row is never changed or removed (the hash chain shows it when the
-- file is edited by other means).
CREATE TRIGGER "history_entry_no_update" BEFORE UPDATE ON "history_entry"
BEGIN
    SELECT RAISE(ABORT, 'history_entry is append-only');
END;

CREATE TRIGGER "history_entry_no_delete" BEFORE DELETE ON "history_entry"
BEGIN
    SELECT RAISE(ABORT, 'history_entry is append-only');
END;

-- A signed bundle is never replaced (DT-13): its key is the lock, a new version is a new row.
CREATE TRIGGER "sync_bundle_no_update" BEFORE UPDATE ON "sync_bundle"
BEGIN
    SELECT RAISE(ABORT, 'sync_bundle rows are never replaced');
END;
